import {profile, projects, skills, experience, articles} from './content.js';
import {CubeScene, BackdropField} from './cube3d.js';
import {cubeSkillFaces,faceForMove} from './cube-skills.js';
import {thoughtsPage,detailShell,hydrateContent,postCard} from './content-ui.js';
import {studioPage,initStudio} from './content-admin.js';
import {renderProjectArtwork} from './project-art.js';
const app=document.getElementById('app');let activeScene=null;let activeFilter='ALL';
const nav=[['/','Home'],['/about','About'],['/projects','Projects'],['/experience','Experience'],['/skills','Skills'],['/journal','Journal'],['/thoughts','Thoughts'],['/contact','Contact']];
const e=(value='')=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const tag=text=>`<span class="pill">${e(text)}</span>`;
function header(route){return `<header class="site-header" id="site-header"><div class="container nav-shell"><a data-link class="brand" href="/" aria-label="Go to homepage"><span class="brand-mark">S</span><span class="brand-text"><strong>Satyajit<span style="color:var(--cyan)">.</span></strong><small>BACKEND & AI ENGINEER</small></span></a><nav class="desktop-nav" aria-label="Main navigation">${nav.map(([url,label])=>`<a data-link href="${url}" class="${route===url||(route.startsWith(url+'/')&&url!=='/')?'active':''}">${label}</a>`).join('')}</nav><div class="nav-actions"><a class="btn btn-ghost btn-small" data-link href="/contact">Let's connect <span>↗</span></a><button id="menu-button" class="mobile-toggle" aria-expanded="false" aria-label="Toggle navigation">☰</button></div></div><nav class="mobile-nav" id="mobile-nav" hidden aria-label="Mobile navigation">${nav.map(([url,label])=>`<a data-link href="${url}" class="${route===url?'active':''}">${label}</a>`).join('')}<a data-link href="/lab">◈ Interactive 3D Lab</a></nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-top"><div><a data-link class="brand" href="/"><span class="brand-mark">S</span><span class="brand-text"><strong>Satyajit<span style="color:var(--cyan)">.</span></strong><small>BACKEND & AI ENGINEER</small></span></a><h3>Let's build something<br/><span class="gradient-text">that matters.</span></h3><p>Thoughtful systems. Useful intelligence. A little curiosity in every line of code.</p></div><div><h4>EXPLORE</h4><div class="footer-links"><a data-link href="/about">About me</a><a data-link href="/projects">Selected projects</a><a data-link href="/experience">Experience</a><a data-link href="/skills">Technology stack</a><a data-link href="/lab">Interactive 3D lab</a></div></div><div><h4>STAY CONNECTED</h4><div class="footer-links"><a data-link href="/contact">Contact / collaboration</a><a data-link href="/guestbook">Guestbook & comments</a><a data-link href="/journal">Engineering journal</a><a data-link href="/thoughts">Thoughts & LinkedIn posts</a><a data-link href="/privacy">Privacy & data</a><a data-link href="/links">All links and demos</a>${profile.github?`<a href="${e(profile.github)}" rel="noopener noreferrer" target="_blank">GitHub ↗</a>`:''}${profile.linkedin?`<a href="${e(profile.linkedin)}" rel="noopener noreferrer" target="_blank">LinkedIn ↗</a>`:''}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Satyajit Sahoo. Built with curiosity and real-time 3D.</span><span>DESIGNED FOR THE NEXT DIMENSION &nbsp; ✦</span></div></div></footer>`;}
const ribbon=()=>`<div class="tech-ribbon"><span class="tech-ribbon-label">TECH STACK</span>${[['🐍','Python'],['◈','FastAPI'],['◉','Django'],['⬡','Next.js'],['⌘','PostgreSQL'],['◫','Docker'],['☁','Cloud'],['✧','LLMs']].map(([ic,t])=>`<span class="pill"><b style="color:#89d5ff">${ic}</b> ${t}</span>`).join('')}</div>`;
function projectArt(p){return `<div class="project-art pa-art--${e(p.slug)}"><span class="art-index">PROJECT // ${e(p.num)}</span><div class="pa-art-content" aria-hidden="true">${renderProjectArtwork(p.slug)}</div><span class="art-label">${e(p.eyebrow)}</span></div>`;}
function projectCard(p){return `<a data-link href="/projects/${p.slug}" class="cube-card project-card ${p.accent}" aria-label="Explore ${e(p.name)} case study">${projectArt(p)}<div class="project-body"><div class="eyebrow">${p.subtitle}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="project-foot"><div class="mini-tags">${p.tags.slice(0,3).map(x=>`<span>${e(x)}</span>`).join('')}</div><span class="arrow-disc">↗</span></div></div></a>`;}
function sectionHeader(label,title,desc,href,cta){return `<div class="section-head"><div><div class="eyebrow">${label}</div><h2 class="section-title">${title}</h2></div><div>${desc?`<p>${desc}</p>`:''}${href?`<a data-link href="${href}" class="btn-link" style="margin-top:15px">${cta||'Explore more'} <span>↗</span></a>`:''}</div></div>`;}
function cubeVisual({kind='hero',notes=true}={}){return `<div class="${kind==='hero'?'hero-visual':'page-visual'}"><canvas class="cube-canvas ${kind==='hero'?'hero-canvas':''}" data-cube="${kind}" aria-label="Rotating interactive three-dimensional holographic Rubik-style cube" role="img"></canvas>${notes?`<div class="holo-note holo-note-left"><small>◉ LIVE SIMULATION</small><strong>3D / INTERACTIVE</strong></div><div class="holo-note holo-note-right"><small>CORE SYSTEM</small><strong><span class="pulse"></span> CREATIVITY + LOGIC</strong></div>`:''}${kind==='hero'?`<div class="cube-controls"><button type="button" id="shuffle-hero" aria-label="Turn top face of the Rubik cube">⟳ &nbsp; TURN U</button><button type="button" data-move="R" aria-label="Turn right face">R ↻</button><button type="button" data-move="F" aria-label="Turn front face">F ↻</button><a class="cube-controls-link" href="#skill-deck" style="background:#121d3bcc;border:1px solid #6571ad55;border-radius:10px;padding:9px 13px;font-size:10px;letter-spacing:.07em;color:#cbdbff;font-weight:700">EXPLORE SKILLS ↓</a><a class="cube-controls-link" data-link href="/lab" style="background:#121d3bcc;border:1px solid #6571ad55;border-radius:10px;padding:9px 13px;font-size:10px;letter-spacing:.07em;color:#cbdbff;font-weight:700">OPEN 3D LAB ↗</a></div>`:''}</div>`;}
const skillTiles=face=>face.skills.map(([abbr,name],index)=>`<div class="cube-skill-tile" role="listitem"><span class="cube-skill-abbr">${e(abbr)}</span><span class="cube-skill-name">${e(name)}</span><small>${String(index+1).padStart(2,'0')}</small></div>`).join('');
function skillDeck(){const face=cubeSkillFaces[0];return `<section class="section-compact skill-deck-section" id="skill-deck"><div class="container"><div class="glass skill-deck"><div class="skill-deck-intro"><div class="eyebrow">THE 3 × 3 SKILLS CUBE</div><h2 class="heading-md">Six faces. <span class="gradient-text">Nine skills each.</span></h2><p>Every square on the cube represents one technology. Turn the Rubik's cube freely, or select a face here to explore its nine skills — three in each row.</p><a data-link class="btn-link" href="/skills">Explore the complete skills directory ↗</a></div><div class="skill-deck-body"><div class="face-switcher" aria-label="Choose a cube skill face">${cubeSkillFaces.map((f,i)=>`<button type="button" class="face-tab ${i===0?'active':''}" data-skill-face="${i}" aria-pressed="${i===0}" style="--face-accent:${f.accent}"><span>${f.side}</span>${e(f.name)}</button>`).join('')}</div><div class="skill-deck-display" id="skill-face-display"><div class="cube-face-heading"><span id="skill-face-heading">${e(face.name)}</span><small>3 × 3 / 09 TECHNOLOGIES</small></div><div class="cube-skill-grid" id="skill-tiles" role="list" aria-label="Nine technologies on the selected cube face">${skillTiles(face)}</div></div></div></div></div></section>`;}
function robotCompanion(){return `<aside class="orbit-guide" id="orbit-guide" aria-label="Friendly portfolio guide"><div class="guide-bubble" id="guide-bubble"><button type="button" class="guide-dismiss" id="guide-dismiss" aria-label="Hide the guide">×</button><small>ORB-I • YOUR TOUR GUIDE</small><p id="guide-message" aria-live="polite">Hi! I’ll show you around.</p></div><button class="guide-robot" id="guide-robot" type="button" aria-label="Toggle the robot guide's message"><span class="guide-antenna"></span><span class="guide-ear guide-ear-left"></span><span class="guide-ear guide-ear-right"></span><span class="guide-face"><i class="guide-eye"></i><i class="guide-eye"></i><span class="guide-smile"></span></span><span class="guide-body"></span></button></aside>`;}
function home(){return `<main class="fade-route"><section class="hero"><div class="container"><div class="hero-grid"><div class="hero-copy"><div class="status">Exploring meaningful engineering opportunities</div><div class="hero-kicker">BACKEND / SYSTEMS / ARTIFICIAL INTELLIGENCE</div><h1 class="display-xl">BUILDING<br/><span class="gradient-text">DIGITAL</span><br/>INTELLIGENCE<span style="color:#7d8cff">.</span></h1><p class="lead">I'm <strong>Satyajit Sahoo</strong> — a Backend & AI Engineer designing reliable systems, building ambitious products, and exploring what happens when <strong>great engineering meets intelligent technology.</strong></p><div class="hero-buttons"><a data-link href="/projects" class="btn btn-primary">Explore my work <span>↗</span></a>${profile.resume?`<a class="btn btn-ghost" href="${e(profile.resume)}" download>Download resume ↓</a>`:`<a data-link href="/contact?topic=Resume%20request" class="btn btn-ghost">Request my resume ↗</a>`}<a data-link href="/links" class="hero-link-hub">All links ↗</a></div><div class="hero-mini"><div><strong>4<span style="color:var(--cyan)">+</span></strong><span>Years in software</span></div><div><strong>${projects.length.toString().padStart(2,'0')}</strong><span>Projects & builds</span></div><div><strong>∞</strong><span>Curiosity to learn</span></div></div></div>${cubeVisual({kind:'hero'})}</div>${ribbon()}</div></section>${skillDeck()}<section class="section floating-section" id="featured"><div class="container">${sectionHeader('01 / SELECTED WORK','Real projects. <span class="gradient-text">Real complexity.</span>','Exploring complex challenges through carefully built systems, helpful intelligence, and intuitive interfaces.','/projects','All case studies')}<div class="projects-grid">${projects.slice(0,3).map(projectCard).join('')}</div></div></section><section class="section"><div class="container">${sectionHeader('02 / WHAT I DO','Technology with <span class="gradient-text">purpose.</span>','The right architecture is invisible. The experience it enables should feel effortless.')}<div class="feature-grid"><div class="glass feature-lead"><div class="eyebrow">THE ENGINEERING MINDSET</div><h3>Vision <span style="color:var(--cyan)">→</span> Code<br/><span class="gradient-text">→ Impact</span></h3><p>From shaping data models to shipping full products, I care about systems that make sense today—and can adapt tomorrow.</p><a data-link class="btn-link" href="/about" style="margin-top:26px">How I work ↗</a></div><div class="glass feature-tile"><div class="feature-icon">⌘</div><div><h3>Systems that scale.</h3><p>Backend architecture, services, databases, permissions, and infrastructure engineered to stay dependable.</p></div></div><div class="glass feature-tile"><div class="feature-icon">✧</div><div><h3>Intelligence in action.</h3><p>Retrieval, LLM workflows, integrations, and practical AI experiences grounded in real product requirements.</p></div></div></div><div class="glass quote-banner"><div><div class="eyebrow">BEYOND THE CODE</div><h3>Complex behind the scenes.<br/><span class="gradient-text">Simple at the surface.</span></h3><p style="margin-top:12px">Engineering should make the experience better, not heavier.</p></div><a data-link href="/skills" class="btn btn-primary">Explore my stack ↗</a></div></div></section><section class="section"><div class="container">${sectionHeader('03 / THE JOURNEY','Built through <span class="gradient-text">experience.</span>','Engineering growth, from production software to evolving product architecture.','/experience','View experience')}<div class="timeline">${experience.map(x=>`<div class="glass time-card"><div class="eyebrow">${x.period}</div><h3>${x.role}</h3><p style="color:#8fd8ff;font-weight:700;margin-bottom:13px">${x.company}</p><p>${x.desc}</p></div>`).join('')}</div></div></section><section class="section-compact"><div class="container"><div class="glass quote-banner"><div><div class="eyebrow">THE OPEN LAB</div><h3>An interactive <span class="gradient-text">3D experiment.</span></h3><p style="margin-top:12px">Rotate the core, move your pointer, and see what happens when code becomes a canvas.</p></div><a data-link class="btn btn-ghost" href="/lab">Enter the 3D lab ↗</a></div></div></section><section class="section"><div class="container">${sectionHeader('04 / ENGINEERING NOTES','Ideas worth <span class="gradient-text">sharing.</span>','Observations from working with architecture, AI, and real product constraints.','/journal','Visit journal')}<div class="journal-grid">${articles.slice(0,3).map(articleCard).join('')}</div></div></section><section class="section-compact latest-stories-section"><div class="container">${sectionHeader('FROM THE ENGINEERING DESK','Latest <span class="gradient-text">writing.</span>','Perspectives on AI, backend systems, and new things I am learning.','/journal','All journal posts')}<div id="homepage-posts" class="content-grid"><p>Loading articles…</p></div></div></section>${bottomCTA()}</main>`;}
function bottomCTA(){return `<section class="section-compact"><div class="container"><div class="glass quote-banner"><div><div class="eyebrow">HAVE AN IDEA?</div><h3>Let's make the next thing <span class="gradient-text">remarkable.</span></h3><p style="margin-top:13px">An idea, a question, or a challenge worth solving—I'm happy to hear it.</p></div><a data-link href="/contact" class="btn btn-primary">Start a conversation ↗</a></div></div></section>`;}
function pageHead(label,title,desc,{scene=false}={}){return `<section class="page-hero"><div class="container">${scene?`<div class="page-head-grid"><div><div class="tagline">${label}</div><h1 class="display-lg">${title}</h1><p class="intro">${desc}</p></div>${cubeVisual({kind:'small',notes:false})}</div>`:`<div class="tagline">${label}</div><h1 class="display-lg">${title}</h1><p class="intro">${desc}</p>`}</div></section>`;}
function about(){return `<main class="fade-route">${pageHead('BEHIND THE CODE','Engineer by craft.<br/><span class="gradient-text">Builder by nature.</span>','I enjoy navigating the space between messy business needs, well-designed systems, and surprisingly simple user experiences.',{scene:true})}<section class="section-compact"><div class="container"><div class="about-grid"><div class="glass about-panel"><div class="eyebrow">MY STORY / AN OPEN SOURCE OF CURIOSITY</div><h2>Curious about the <span class="gradient-text">whole system.</span></h2><p>My work lives across backend engineering, APIs, database design, full-stack product development, and emerging AI applications. I enjoy tracing a challenge to its foundations and building a solution that holds up under real-world use.</p><p>I've contributed to software in enterprise environments and continued exploring my own projects—from configurable operational platforms to HR workflows and AI-powered experiences.</p><p>For me, great engineering is equal parts clarity, craft, collaboration, and the discipline to keep learning.</p></div><div class="about-aside"><div class="glass stat-panel"><span>EXPERIENCE IN SOFTWARE</span><b>4+</b><span>Years of learning, building, and improving.</span></div><div class="glass stat-panel"><span>FAVORITE PROBLEM SPACE</span><b style="font-size:47px">AI × API</b><span>Turning complex capabilities into practical products.</span></div></div></div></div></section><section class="section"><div class="container">${sectionHeader('HOW I THINK','Principles over <span class="gradient-text">buzzwords.</span>','A few beliefs that shape my engineering decisions.')}<div class="values-grid"><div class="glass value-card"><span>◈</span><h3>Clarity first.</h3><p>Understand the problem, define boundaries, and choose abstractions that make the system simpler.</p></div><div class="glass value-card"><span>✧</span><h3>Build to adapt.</h3><p>Ship useful software now while leaving room for growth and better decisions tomorrow.</p></div><div class="glass value-card"><span>⌁</span><h3>Never stop asking.</h3><p>Challenge assumptions, measure outcomes, learn continuously, and enjoy the hard problems.</p></div></div></div></section>${bottomCTA()}</main>`;}
function projectCatalog(){return `<main class="fade-route">${pageHead('CURATED PROJECTS / REAL WORK','Ideas turned into<br/><span class="gradient-text">working systems.</span>','Selected products and platforms spanning multi-tenant architecture, enterprise systems, and intelligent consumer experiences.',{scene:true})}<section class="section-compact"><div class="container"><div class="filter-row" role="group" aria-label="Filter projects">${['ALL','ENTERPRISE','SAAS','AI','PRODUCT','IOT','AUTOMATION'].map(f=>`<button class="filter-button ${activeFilter===f?'active':''}" data-filter="${f}" aria-pressed="${activeFilter===f}">${f}</button>`).join('')}</div><div class="catalog-grid" id="catalog-grid">${projects.filter(filterProject).map(projectCard).join('')}</div></div></section>${bottomCTA()}</main>`;}
function filterProject(p){if(activeFilter==='ALL')return true;const group=(p.eyebrow||'').toUpperCase();return group.includes(activeFilter)||(activeFilter==='AI'&&p.tags.some(t=>/AI|LLM|RAG|LANGCHAIN|LANGGRAPH|TENSORFLOW|KERAS|LSTM/i.test(t)));}
function projectDetail(p){return `<main class="fade-route"><section class="page-hero detail-hero"><div class="container"><div class="breadcrumb"><a data-link href="/projects">← All Projects</a><span>/</span>${p.name}</div><div class="tagline">${p.eyebrow} / CASE STUDY ${p.num}</div><h1 class="display-lg">${p.name}<br/><span class="gradient-text">${p.subtitle}.</span></h1><p class="intro">${p.desc}</p></div></section><section class="section-compact"><div class="container"><div style="max-width:900px;margin-bottom:28px" class="cube-card ${p.accent}">${projectArt(p)}</div><div class="detail-layout"><div class="glass detail-body"><div class="eyebrow">THE CONTEXT</div><h2 style="margin-top:14px">The problem worth solving.</h2><p>${p.challenge}</p><h3>How I approached it</h3><p>${p.approach}</p><h3>Engineering highlights</h3><ul class="detail-list">${p.architecture.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p class="disclaimer">${p.note}</p></div><aside class="glass detail-aside"><div class="eyebrow">PROJECT OVERVIEW</div><h3>${p.name}</h3><p>${p.subtitle}</p><h3 style="margin-top:29px">Core technologies</h3><div class="skill-tags">${p.tags.map(s=>`<span>${e(s)}</span>`).join('')}</div>${p.url?`<a href="${e(p.url)}" target="_blank" rel="noopener noreferrer" class="btn btn-ghost" style="margin-top:27px;width:100%">Project link ↗</a>`:''}<a data-link href="/contact?topic=${encodeURIComponent('Question about '+p.name)}" class="btn btn-primary" style="margin-top:12px;width:100%">Discuss this project ↗</a></aside></div></div></section><section class="section-compact"><div class="container">${sectionHeader('KEEP EXPLORING','Other selected <span class="gradient-text">work.</span>')}<div class="projects-grid">${projects.filter(x=>x.slug!==p.slug).slice(0,3).map(projectCard).join('')}</div></div></section></main>`;}
function experiencePage(){return `<main class="fade-route">${pageHead('THE PATH SO FAR','Learning. Shipping.<br/><span class="gradient-text">Growing.</span>','Experience across engineering teams, enterprise software, application architecture, and product development.',{scene:true})}<section class="section-compact"><div class="container">${sectionHeader('PROFESSIONAL EXPERIENCE','Where the work <span class="gradient-text">happened.</span>')}<div class="timeline">${experience.map(x=>`<article class="glass time-card"><div class="eyebrow">${x.period}</div><h3>${x.role}</h3><div style="font-size:14px;color:#85ceff;margin-bottom:15px;font-weight:700">${x.company}</div><p>${x.desc}</p></article>`).join('')}</div><div class="glass quote-banner"><div><div class="eyebrow">LOOKING FORWARD</div><h3>Always curious about <span class="gradient-text">what's next.</span></h3><p style="margin-top:12px">Backend systems, full-stack platforms, and useful applications of AI.</p></div><a data-link href="/contact" class="btn btn-ghost">Let's talk ↗</a></div></div></section></main>`;}
function skillsPage(){return `<main class="fade-route">${pageHead('TECHNICAL EXPERTISE','The tools change.<br/><span class="gradient-text">The thinking stays.</span>','A practical stack for creating scalable APIs, usable interfaces, intelligent workflows, and dependable infrastructure.',{scene:true})}<section class="section-compact"><div class="container"><div class="skill-grid">${skills.map(s=>`<article class="glass skill-card"><div class="skill-icon">${s.icon}</div><h3>${s.cat}</h3><p>${s.desc}</p><div class="skill-tags">${s.stack.map(t=>`<span>${e(t)}</span>`).join('')}</div></article>`).join('')}</div><div class="glass architecture" style="margin-top:23px"><div class="eyebrow">SYSTEM DESIGN / EXAMPLE ARCHITECTURE</div><h3 class="heading-md" style="margin-top:16px">Every layer has a job.</h3><p style="margin-top:8px">A simplified illustration of how components can work together, not a claim about any particular project's deployment.</p><div class="arch-diagram"><div class="arch-box"><small>EXPERIENCE</small>Next.js / React</div><span class="arch-arrow">→</span><div class="arch-box"><small>API & BUSINESS LOGIC</small>Python / FastAPI</div><span class="arch-arrow">→</span><div class="arch-box"><small>DATA</small>PostgreSQL / Redis</div><span class="arch-arrow">↔</span><div class="arch-box"><small>INTELLIGENCE</small>LLMs / Retrieval</div></div></div></div></section>${bottomCTA()}</main>`;}
function articleCard(a,i){let idx=articles.indexOf(a)+1;return `<a data-link href="/journal/${a.slug}" class="cube-card article-card"><div class="eyebrow">${a.tag}</div><div class="journal-no">0${idx}</div><h3>${a.title}</h3><p>${a.summary}</p><div class="read-row"><span class="eyebrow">${a.time}</span><span class="arrow-disc">↗</span></div></a>`;}
function journal(){return `<main class="fade-route">${pageHead('ENGINEERING JOURNAL','Notes from<br/><span class="gradient-text">the build process.</span>','Engineering insights, stories, and LinkedIn posts republished here, with images linked directly to their original sources.',{scene:true})}<section class="section-compact"><div class="container">${sectionHeader('LATEST / FROM THE STUDIO','Published <span class="gradient-text">stories.</span>')}<div class="content-grid" id="dynamic-blog-posts"><p>Loading latest writing…</p></div><div class="journal-archive-heading">${sectionHeader('EVERGREEN / ENGINEERING NOTES','Earlier <span class="gradient-text">notes.</span>')}</div><div class="journal-grid">${articles.map(articleCard).join('')}</div></div></section>${bottomCTA()}</main>`;}
function journalDetail(a){return `<main class="fade-route"><section class="page-hero"><div class="container"><div class="breadcrumb"><a data-link href="/journal">← Journal</a><span>/</span>${a.tag}</div><div class="tagline">${a.date} / ${a.time}</div><h1 class="display-lg" style="max-width:900px">${a.title}</h1><p class="intro">${a.summary}</p></div></section><section class="section-compact"><div class="container"><article class="glass article-body"><div class="eyebrow">NOTES FROM THE ENGINEERING DESK</div>${a.body.map(([heading,body])=>`<h2>${heading}</h2><p>${body}</p>`).join('')}<p class="disclaimer" style="margin-top:35px">Written as general engineering guidance. Validate architecture decisions against your system's requirements.</p><a data-link href="/journal" class="btn btn-ghost" style="margin-top:28px">← Back to journal</a></article></div></section></main>`;}
function contact(){const params=new URLSearchParams(location.search);const topic=params.get('topic')||'';return `<main class="fade-route">${pageHead('CONTACT / COLLABORATION','Good ideas start with<br/><span class="gradient-text">a conversation.</span>','Have a challenging backend problem, an AI product idea, a collaboration proposal, or just a question? Send me a note.')}<section class="section-compact"><div class="container"><div class="contact-grid"><div class="glass contact-info"><div><div class="eyebrow">DIRECT CONNECTION</div><h2>Let's build what<br/><span class="gradient-text">comes next.</span></h2><p>Share the context, what you're working on, and how I can help. I read messages sent through this website.</p></div><div><div class="contact-methods">${profile.email?`<a href="mailto:${e(profile.email)}"><span>✉ Email</span><span>${e(profile.email)} ↗</span></a>`:''}${profile.linkedin?`<a href="${e(profile.linkedin)}" rel="noopener noreferrer" target="_blank"><span>◉ LinkedIn</span><span>Connect ↗</span></a>`:''}${profile.github?`<a href="${e(profile.github)}" rel="noopener noreferrer" target="_blank"><span>⌘ GitHub</span><span>Explore ↗</span></a>`:''}<div><span>◈ Based in</span><span>India · Remote-friendly</span></div><a data-link href="/guestbook"><span>✧ Public guestbook</span><span>Leave a note ↗</span></a><a data-link href="/links"><span>↗ All links</span><span>Profiles & demos ↗</span></a></div><p style="font-size:11px">Your message is saved privately on the server. If an email webhook is configured, a notification can also be sent.</p></div></div><div class="glass contact-form"><div class="eyebrow">SEND A MESSAGE</div><h2 class="heading-md" style="margin:13px 0 25px">Tell me about it.</h2><form id="contact-form"><div class="form-grid"><div class="field"><label for="contact-name">Your name *</label><input id="contact-name" name="name" placeholder="What should I call you?" required minlength="2" maxlength="80" autocomplete="name" /></div><div class="field"><label for="contact-email">Email address *</label><input id="contact-email" type="email" name="email" placeholder="you@example.com" autocomplete="email" required maxlength="200" /></div></div><div class="field"><label for="contact-subject">What is this about? *</label><input id="contact-subject" name="subject" value="${e(topic)}" placeholder="Project collaboration, hiring, question..." required minlength="3" maxlength="120" /></div><div class="field"><label for="contact-message">Your message *</label><textarea id="contact-message" name="message" minlength="20" maxlength="4000" required placeholder="Tell me a little about your idea or the problem you're solving..."></textarea></div><div class="hidden-field" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off" /></label></div><div class="form-footer"><button class="btn btn-primary" type="submit">Send message <span>↗</span></button><span class="disclaimer">* Required fields</span></div><div id="contact-response" class="form-response" role="status" aria-live="polite"></div></form></div></div></div></section></main>`;}
function guestbook(){return `<main class="fade-route">${pageHead('COMMUNITY / GUESTBOOK','Words worth<br/><span class="gradient-text">keeping.</span>','An open space for a thought, a greeting, a question, or a quick note about the work. Messages appear publicly after review.')}<section class="section-compact"><div class="container"><div class="guestbook-grid"><div class="glass guestbook-form"><div class="eyebrow">LEAVE A NOTE</div><h2 class="heading-md" style="margin:14px 0 12px">Sign the guestbook.</h2><p style="font-size:13px;margin-bottom:24px">A little internet corner for thoughtful feedback. No account required.</p><form id="guestbook-form"><div class="field"><label for="guest-name">Your name</label><input id="guest-name" name="name" required minlength="2" maxlength="65" placeholder="Your name" /></div><div class="field"><label for="guest-message">Your message</label><textarea id="guest-message" name="message" required minlength="8" maxlength="700" placeholder="What would you like to share?"></textarea></div><div class="hidden-field" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off" /></label></div><button type="submit" class="btn btn-primary">Post for review ↗</button><div id="guestbook-response" class="form-response" aria-live="polite" role="status"></div></form><p class="disclaimer" style="margin-top:8px">For privacy, don't include personal information. Notes are moderated before appearing here.</p></div><div><div class="section-head" style="margin-bottom:18px"><div><div class="eyebrow">THE WALL</div><h2 class="heading-md" style="margin-top:8px">Community notes <span style="color:var(--cyan)" id="guest-count"></span></h2></div></div><div class="guestbook-list" id="guestbook-list"><div class="glass empty-state"><div class="empty-symbol">✧</div><h3>Loading notes...</h3></div></div></div></div></div></section></main>`;}
function lab(){return `<main class="fade-route">${pageHead('EXPERIMENTAL / 3D LAB','Engineering, but<br/><span class="gradient-text">make it tangible.</span>','This is not a wallpaper. Each cubie is modeled in 3D space, individually projected, lit, and moved as you interact with the scene.')}<section class="section-compact"><div class="container"><div class="lab-layout"><div class="glass lab-stage"><canvas class="cube-canvas" data-cube="lab" aria-label="Interactive Rubik-style three-dimensional cube" role="img"></canvas><div class="holo-note" style="left:20px;top:20px"><small>SCENE 01 / LIVE</small><strong>HOLOGRAPHIC CORE</strong></div></div><div class="glass lab-controls"><div class="eyebrow">THE CONTROL DECK</div><h2>Play with the <span class="gradient-text">dimension.</span></h2><p>Drag the cube to change the viewing angle. Turn any face, middle slice or the entire cube; try scrambling and resetting it.</p><div class="control-group"><h4>01 / TURN ANY FACE OR SLICE</h4><p>R/L = sides · U/D = top/bottom · F/B = front/back · M/E/S = middle layers · X/Y/Z = entire cube. A prime (′) turns the other way.</p><div class="cube-turn-grid" aria-label="Cube rotation controls"><div class="turn-control"><button type="button" data-move="R" aria-label="R clockwise">R</button><button type="button" data-move="R'" aria-label="R counterclockwise">R′</button></div><div class="turn-control"><button type="button" data-move="L" aria-label="L clockwise">L</button><button type="button" data-move="L'" aria-label="L counterclockwise">L′</button></div><div class="turn-control"><button type="button" data-move="U" aria-label="U clockwise">U</button><button type="button" data-move="U'" aria-label="U counterclockwise">U′</button></div><div class="turn-control"><button type="button" data-move="D" aria-label="D clockwise">D</button><button type="button" data-move="D'" aria-label="D counterclockwise">D′</button></div><div class="turn-control"><button type="button" data-move="F" aria-label="F clockwise">F</button><button type="button" data-move="F'" aria-label="F counterclockwise">F′</button></div><div class="turn-control"><button type="button" data-move="B" aria-label="B clockwise">B</button><button type="button" data-move="B'" aria-label="B counterclockwise">B′</button></div><div class="turn-control"><button type="button" data-move="M" aria-label="M clockwise">M</button><button type="button" data-move="M'" aria-label="M counterclockwise">M′</button></div><div class="turn-control"><button type="button" data-move="E" aria-label="E clockwise">E</button><button type="button" data-move="E'" aria-label="E counterclockwise">E′</button></div><div class="turn-control"><button type="button" data-move="S" aria-label="S clockwise">S</button><button type="button" data-move="S'" aria-label="S counterclockwise">S′</button></div><div class="turn-control"><button type="button" data-move="X" aria-label="X clockwise">X</button><button type="button" data-move="X'" aria-label="X counterclockwise">X′</button></div><div class="turn-control"><button type="button" data-move="Y" aria-label="Y clockwise">Y</button><button type="button" data-move="Y'" aria-label="Y counterclockwise">Y′</button></div><div class="turn-control"><button type="button" data-move="Z" aria-label="Z clockwise">Z</button><button type="button" data-move="Z'" aria-label="Z counterclockwise">Z′</button></div></div><div class="cube-action-row"><button class="btn btn-primary" type="button" data-cube-action="scramble">⇄ Scramble</button><button class="btn btn-ghost" type="button" data-cube-action="reset">↺ Reset solved cube</button></div><div id="cube-status" role="status" aria-live="polite" class="cube-status">Ready. Drag to orbit, or choose a turn.</div></div><div class="control-group"><h4>02 / SCROLL + DRAG</h4><p>On the homepage, your scroll position affects the core's rotation and gently separates its cubies.</p><a data-link class="btn btn-ghost" href="/" style="margin-top:14px">Experience on homepage ↗</a></div><div class="control-group"><h4>03 / ACTUAL PUZZLE STATE</h4><p>Every turn saves piece position and sticker orientation, so the next turn starts from the last state. It is not a one-off twist animation.</p></div></div></div></div></section></main>`;}
function privacy(){return `<main class="fade-route">${pageHead('PRIVACY / TRANSPARENCY','Respect for your <span class="gradient-text">information.</span>','A plain-language explanation of how this portfolio handles contact messages and public guestbook entries.')}<section class="section-compact"><div class="container"><article class="glass article-body"><h2>Contact messages</h2><p>When you submit the contact form, your name, email address, subject and message are stored privately on the website server so the site owner can respond. They are not made public. An optional notification webhook can forward these details to a service configured by the owner.</p><h2>Guestbook notes</h2><p>Your guestbook name and message are reviewed before publication. Approved entries appear publicly with their date. Do not submit sensitive personal information in public messages.</p><h2>Data storage</h2><p>This starter project uses a private server-side file store. The host and site owner are responsible for securing storage, backups, access and retention. There are no built-in tracking cookies or analytics integrations.</p><h2>Correction or removal</h2><p>Use the <a data-link href="/contact" style="color:var(--cyan)">contact form</a> to request correction or removal of information you submitted. The site owner must perform removal from the stored records.</p><p class="disclaimer" style="margin-top:24px">Template privacy notice. The operator should review and update this page for their deployment, location, retention practices and legal obligations.</p></article></div></section></main>`;}
function admin(){return `<main class="fade-route">${pageHead('OWNER / CONTROL DECK','Private message <span class="gradient-text">console.</span>','Review contact submissions and approve public guestbook notes. Requires an ADMIN_TOKEN configured on the server.')}<section class="section-compact"><div class="container"><div class="glass admin-shell"><div id="admin-login"><div class="eyebrow">AUTHENTICATION REQUIRED</div><h2 class="heading-md" style="margin:14px 0">Unlock the console.</h2><form id="admin-form" class="form-footer"><input id="admin-token" type="password" autocomplete="off" placeholder="ADMIN_TOKEN" aria-label="Admin token" required /><button class="btn btn-primary" type="submit">Unlock →</button></form><div id="admin-error" class="form-response" role="status"></div></div><div id="admin-dashboard" hidden><div class="studio-nav"><a data-link href="/admin/content" class="btn btn-primary btn-small">✦ Open Content Studio ↗</a><a data-link href="/journal">Public journal ↗</a><a data-link href="/thoughts">Thoughts ↗</a></div><div class="section-head"><div><div class="eyebrow">PRIVATE / ADMINISTRATION</div><h2 class="heading-md" style="margin-top:10px">Incoming signals.</h2></div><button id="admin-lock" class="btn btn-ghost btn-small">Lock console</button></div><div class="filter-row"><button data-admin-tab="pending" class="filter-button active">Awaiting review</button><button data-admin-tab="all" class="filter-button">All guestbook notes</button><button data-admin-tab="inbox" class="filter-button">Contact inbox</button></div><div id="admin-list"></div></div></div></div></section></main>`;}
function notFound(){return `<main class="fade-route">${pageHead('404 / SIGNAL LOST','This route is<br/><span class="gradient-text">off the grid.</span>','The page you tried to reach does not exist.') }<section class="section-compact"><div class="container"><a data-link href="/" class="btn btn-primary">← Return home</a></div></section></main>`;}
function linksPage(){const available=[...profile.links,...(profile.resume?[{label:'Resume / CV',url:profile.resume}]:[]),...(profile.hackathon?[{label:'Hackathons',url:profile.hackathon}]:[])];return `<main class="fade-route">${pageHead('LINKS / OPEN SOURCES','Explore the work.<br/><span class="gradient-text">Follow the ideas.</span>','Verified profiles, demos and project references. Resume and hackathon links appear when configured.')}<section class="section-compact"><div class="container"><div class="links-grid">${available.map(x=>`<a class="glass external-link-card" href="${e(x.url)}" target="_blank" rel="noopener noreferrer"><span>${e(x.label)}</span><strong>↗</strong></a>`).join('')}</div>${sectionHeader('PUBLIC DEMOS','Projects with <span class="gradient-text">links.</span>')}<div class="links-grid">${projects.filter(p=>p.url).map(p=>`<a href="${e(p.url)}" target="_blank" rel="noopener noreferrer" class="glass external-link-card"><span>${e(p.name)}</span><strong>↗</strong></a>`).join('')}</div></div></section>${bottomCTA()}</main>`;}
function routeContent(route){if(route==='/')return home();if(route==='/about')return about();if(route==='/projects')return projectCatalog();if(route==='/experience')return experiencePage();if(route==='/skills')return skillsPage();if(route==='/journal')return journal();if(route==='/thoughts')return thoughtsPage();if(route==='/guestbook')return guestbook();if(route==='/contact')return contact();if(route==='/lab')return lab();if(route==='/links')return linksPage();if(route==='/admin')return admin();if(route==='/admin/content')return studioPage();if(route==='/privacy')return privacy();if(route.startsWith('/projects/')){const p=projects.find(x=>'/projects/'+x.slug===route);return p?projectDetail(p):notFound();}if(route.startsWith('/journal/')){const a=articles.find(x=>'/journal/'+x.slug===route);return a?journalDetail(a):detailShell();}return notFound();}
function initScenes(){const canvas=document.querySelector('[data-cube]');if(!canvas)return;activeScene=new CubeScene(canvas,{compact:canvas.dataset.cube!=='hero'});document.getElementById('shuffle-hero')?.addEventListener('click',()=>{activeScene?.turn('U');showSkillFace(4);});document.querySelectorAll('[data-move]').forEach(btn=>btn.addEventListener('click',()=>{activeScene?.turn(btn.dataset.move);const selectedFace=faceForMove(btn.dataset.move);if(selectedFace!==null)showSkillFace(selectedFace);const status=document.getElementById('cube-status');if(status)status.textContent='Queued '+btn.dataset.move+' · drag to orbit';}));document.querySelectorAll('[data-cube-action]').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.cubeAction==='scramble')activeScene?.scramble();else activeScene?.reset();const status=document.getElementById('cube-status');if(status)status.textContent=btn.dataset.cubeAction==='scramble'?'Scrambling all layers…':'Solved state restored.';}));}
function showSkillFace(index){const face=cubeSkillFaces[index];if(!face)return;activeScene?.setSkillFace(index);const name=document.getElementById('skill-face-heading'),tiles=document.getElementById('skill-tiles');if(name)name.textContent=face.name;if(tiles)tiles.innerHTML=skillTiles(face);document.querySelectorAll('[data-skill-face]').forEach(btn=>{const current=Number(btn.dataset.skillFace)===index;btn.classList.toggle('active',current);btn.setAttribute('aria-pressed',String(current));});}
function initSkillDeck(){document.querySelectorAll('[data-skill-face]').forEach(btn=>btn.addEventListener('click',()=>showSkillFace(Number(btn.dataset.skillFace))));}
let cleanupRobot=null;
function initRobotGuide(){
 const guide=document.getElementById('orbit-guide');if(!guide)return;
 let frame=0,closed=false,lastStage=-1,active=true;
 const route=location.pathname;
 const messages=route==='/thoughts'?['Welcome to my thoughts! ✨','These short notes began as lessons and ideas.','Tap a post to explore its original LinkedIn link.']:
 route==='/journal'||route.startsWith('/journal/')?['Welcome to the engineering journal!','Articles and insights are saved here.','More stories ahead. ✨']:
 route==='/projects'?['These are my engineering builds!','Each project has a different story.','See something interesting? Open its case study!']:
 route==='/skills'?['Let me introduce the technologies I use.','A good tool is useful when it solves a real problem.']:
 route==='/contact'?['Have a question? Send me a note!','I would love to hear what you are building.']:
 ['Hi, I’m ORB-I! 👋 Welcome to Satyajit’s portfolio.','See the 3×3 skills on every cube face!','Here are the real-world projects.','I build backend systems and AI workflows.','Here’s the engineering journey.','Ready to explore the 3D Lab?','Fresh writing appears below. ✨'];
 const segments=Array.from(document.querySelectorAll('main > section'));
 const bubble=document.getElementById('guide-bubble'),label=document.getElementById('guide-message');
 const activate=()=>{if(active&&!closed){guide.classList.add('guide-visible');if(label)label.textContent=messages[0];}};
 const delay=window.setTimeout(activate,500);
 const update=()=>{frame=0;if(!active||closed)return;
  let section=0;for(let i=0;i<segments.length;i++)if(segments[i].getBoundingClientRect().top<window.innerHeight*.58)section=i;
  if(section!==lastStage){lastStage=section;if(label)label.textContent=messages[Math.min(section,messages.length-1)];guide.dataset.stage=String(section);}
  // At the footer the guide docks away. It returns when the user scrolls up.
  const nearBottom=(document.documentElement.scrollHeight-window.scrollY-window.innerHeight)<140;
  guide.classList.toggle('guide-visible',!nearBottom);
 };
 const onScroll=()=>{if(!frame)frame=requestAnimationFrame(update)};
 window.addEventListener('scroll',onScroll,{passive:true});
 window.addEventListener('resize',onScroll,{passive:true});
 document.getElementById('guide-dismiss')?.addEventListener('click',()=>{bubble?.classList.add('guide-bubble-hidden');});
 document.getElementById('guide-robot')?.addEventListener('click',()=>{bubble?.classList.toggle('guide-bubble-hidden');guide.classList.add('guide-visible')});
 cleanupRobot=()=>{active=false;window.clearTimeout(delay);if(frame)cancelAnimationFrame(frame);window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',onScroll)};
 update();
}
function updateSticky(){document.getElementById('site-header')?.classList.toggle('scrolled',scrollY>12);document.getElementById('scroll-top')?.classList.toggle('visible',scrollY>460);}
function render(){if(cleanupRobot){cleanupRobot();cleanupRobot=null;}const route=location.pathname.replace(/\/+$/,'')||'/';if(activeScene){activeScene.destroy();activeScene=null;}activeFilter='ALL';app.innerHTML=header(route)+routeContent(route)+footer()+(route==='/admin'||route==='/admin/content'?'':robotCompanion())+`<button id="scroll-top" class="scroll-top" aria-label="Back to top">↑</button>`;document.title=(route==='/'?'Satyajit — Backend & AI Engineer':`${(route.split('/').filter(Boolean).pop()||'Portfolio').replaceAll('-',' ')} | Satyajit`) ;document.getElementById('scroll-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));const menu=document.getElementById('menu-button'),panel=document.getElementById('mobile-nav');menu.addEventListener('click',()=>{panel.hidden=!panel.hidden;menu.setAttribute('aria-expanded',String(!panel.hidden));menu.textContent=panel.hidden?'☰':'✕';});initScenes();initSkillDeck();initRobotGuide();initReveal();bindForms();initStudio();hydrateContent(route);if(route==='/admin')bindAdmin();if(route==='/guestbook')loadGuestbook();updateSticky();}
function initReveal(){if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const io=new IntersectionObserver(entries=>{for(const item of entries)if(item.isIntersecting){item.target.classList.add('revealed');io.unobserve(item.target)}},{threshold:.08});
 document.querySelectorAll('.section-head,.feature-tile,.feature-lead,.project-card,.skill-card,.article-card,.time-card').forEach(el=>io.observe(el));
 if(matchMedia('(pointer:fine)').matches){document.querySelectorAll('.project-card').forEach(card=>{card.addEventListener('pointermove',ev=>{const b=card.getBoundingClientRect(),x=((ev.clientX-b.left)/b.width-.5)*7,y=((ev.clientY-b.top)/b.height-.5)*-5;card.style.transform=`perspective(1050px) rotateY(${x.toFixed(2)}deg) rotateX(${y.toFixed(2)}deg) translateY(-4px)`;});card.addEventListener('pointerleave',()=>card.style.transform='');});}
}
function navigate(href){const u=new URL(href,location.origin);if(u.origin!==location.origin)return;history.pushState({},'',u.pathname+u.search);window.scrollTo({top:0,behavior:'instant'});render();}
document.addEventListener('click',event=>{const link=event.target.closest('a[data-link]');if(link){event.preventDefault();navigate(link.href);return;}const f=event.target.closest('button[data-filter]');if(f){activeFilter=f.dataset.filter;document.querySelectorAll('button[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===activeFilter);b.setAttribute('aria-pressed',String(b.dataset.filter===activeFilter))});const grid=document.getElementById('catalog-grid');if(grid)grid.innerHTML=projects.filter(filterProject).map(projectCard).join('');}});
window.addEventListener('popstate',render);window.addEventListener('scroll',updateSticky,{passive:true});
function formData(form){return Object.fromEntries(new FormData(form).entries());}
async function postForm(form,endpoint,response){const button=form.querySelector('button[type="submit"]');button.disabled=true;response.classList.remove('error');response.textContent='Submitting securely...';try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formData(form))});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to submit at the moment');response.textContent=data.message||(endpoint.includes('contact')?'Message received!':'Your note has been submitted for review.');form.reset();return true;}catch(error){response.textContent=error.message;response.classList.add('error');return false;}finally{button.disabled=false;}}
function bindForms(){const contact=document.getElementById('contact-form');if(contact){contact.addEventListener('submit',async ev=>{ev.preventDefault();await postForm(contact,'/api/contact',document.getElementById('contact-response'));});}const guest=document.getElementById('guestbook-form');if(guest){guest.addEventListener('submit',async ev=>{ev.preventDefault();const ok=await postForm(guest,'/api/guestbook',document.getElementById('guestbook-response'));if(ok)loadGuestbook();});}}
async function loadGuestbook(){const list=document.getElementById('guestbook-list'),counter=document.getElementById('guest-count');if(!list)return;try{let r=await fetch('/api/guestbook');if(!r.ok)throw Error('Could not load notes');const data=await r.json();if(!document.contains(list))return;counter.textContent=`(${data.entries.length})`;list.replaceChildren();if(!data.entries.length){list.innerHTML=`<div class="glass empty-state"><div class="empty-symbol">✧</div><h3>Be the first to say hello.</h3><p>The guestbook is still waiting for its first approved message. Leave a kind thought and help start the conversation.</p></div>`;return;}for(const item of data.entries){const article=document.createElement('article');article.className='glass guestbook-item';const row=document.createElement('div');row.className='guestbook-name';const avatar=document.createElement('div');avatar.className='avatar';avatar.textContent=item.name.trim().charAt(0).toUpperCase();const wrap=document.createElement('div');const name=document.createElement('b');name.textContent=item.name;const date=document.createElement('span');date.textContent=new Date(item.createdAt).toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'});wrap.append(name,date);row.append(avatar,wrap);const message=document.createElement('p');message.textContent=item.message;article.append(row,message);list.append(article);}}catch(err){list.innerHTML='<div class="glass empty-state"><h3>Notes unavailable</h3><p>Please try again later.</p></div>';}}
render();

function bindAdmin(){const form=document.getElementById('admin-form');if(!form)return;const login=document.getElementById('admin-login'),dash=document.getElementById('admin-dashboard'),error=document.getElementById('admin-error');let current='pending';
 async function api(path,method='GET'){const r=await fetch(path,{method,headers:{authorization:'Bearer '+(sessionStorage.getItem('orbit_admin_token')||'')}});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
 async function reload(){const list=document.getElementById('admin-list');list.innerHTML='<p>Loading…</p>';try{const response=await api(current==='inbox'?'/api/admin/inbox':'/api/admin/guestbook');const entries=current==='pending'?response.entries.filter(x=>x.status==='pending'):response.entries;if(!entries.length){list.innerHTML='<div class="glass empty-state"><div class="empty-symbol">✧</div><h3>All clear.</h3><p>Nothing waiting in this view.</p></div>';return;}list.innerHTML=entries.map(x=>`<article class="glass admin-item"><div><span class="eyebrow">${e(x.createdAt)} ${x.status?' / '+e(x.status):''}</span><h3>${e(x.name)}${x.email?` · <span style="color:#8dc6ef;font-size:13px">${e(x.email)}</span>`:''}</h3>${x.subject?`<p style="color:#a2e7fa">${e(x.subject)}</p>`:''}<p>${e(x.message)}</p></div>${x.status==='pending'?`<div class="admin-buttons"><button class="btn btn-primary btn-small" data-approve="${e(x.id)}">Approve</button><button class="btn btn-ghost btn-small" data-reject="${e(x.id)}">Reject</button></div>`:''}</article>`).join('');}catch(err){list.innerHTML='';error.textContent=err.message;error.classList.add('error');}}
 function show(){login.hidden=true;dash.hidden=false;reload();}
 form.addEventListener('submit',async ev=>{ev.preventDefault();sessionStorage.setItem('orbit_admin_token',document.getElementById('admin-token').value);error.textContent='';try{await api('/api/admin/guestbook');show();}catch(err){sessionStorage.removeItem('orbit_admin_token');error.textContent=err.message;error.classList.add('error');}});
 document.getElementById('admin-lock').addEventListener('click',()=>{sessionStorage.removeItem('orbit_admin_token');dash.hidden=true;login.hidden=false;document.getElementById('admin-token').value='';});
 dash.addEventListener('click',async ev=>{const tab=ev.target.closest('[data-admin-tab]');if(tab){current=tab.dataset.adminTab;dash.querySelectorAll('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===tab));reload();return;}const action=ev.target.closest('[data-approve],[data-reject]');if(action){const decision=action.dataset.approve?'approve':'reject',id=action.dataset.approve||action.dataset.reject;action.disabled=true;try{await api(`/api/admin/guestbook/${id}/${decision}`,'POST');reload();}catch(err){error.textContent=err.message;error.classList.add('error');action.disabled=false;}}});
 if(sessionStorage.getItem('orbit_admin_token'))api('/api/admin/guestbook').then(show).catch(()=>sessionStorage.removeItem('orbit_admin_token'));
}

const globalBackdrop=document.getElementById('world-canvas');if(globalBackdrop && !matchMedia('(prefers-reduced-motion: reduce)').matches)new BackdropField(globalBackdrop);
